"use client";

import HeroBlock from "@/components/Hero";
import ProjectCard from "@/components/ProjectCard";
import { PERSON } from "@/lib/data";
import { motion } from "framer-motion";

export default function Home() {
    const sectionVariants = {
        initial: { opacity: 0, y: 30 },
        whileInView: { opacity: 1, y: 0 },
        viewport: { once: true, margin: "-100px" }
    };

    return (
        <main className="relative bg-[#0B0F14] min-h-screen">
            {/* Premium Background Layer */}
            <div className="mesh-bg" />
            <div className="grid-overlay" />

            <HeroBlock person={PERSON} />

            {/* WORK SECTION - Scroll Reveal */}
            <motion.section
                id="work"
                initial="initial"
                whileInView="whileInView"
                viewport={sectionVariants.viewport}
                variants={sectionVariants}
                transition={{ duration: 0.8, ease: [0.22, 0.61, 0.36, 1] }}
                className="relative z-10 py-32 px-6 md:px-12 max-w-7xl mx-auto"
            >
                <div className="flex flex-col md:flex-row justify-between items-end mb-20">
                    <div className="space-y-4">
                        <span className="text-accent font-bold tracking-[0.2em] text-xs uppercase">Portfolio</span>
                        <h2 className="font-tight text-5xl md:text-6xl font-bold">Selected Project.</h2>
                    </div>
                    <p className="text-[#9AA3B2] max-w-sm text-right mt-6 md:mt-0 leading-relaxed font-light">
                        Meticuously crafted solutions bridging human intent and technical execution.
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    {PERSON.projects.map((project, idx) => (
                        <ProjectCard key={idx} project={project} index={idx} />
                    ))}
                </div>
            </motion.section>

            {/* SERVICES SECTION - Scroll Reveal */}
            <motion.section
                initial="initial"
                whileInView="whileInView"
                viewport={sectionVariants.viewport}
                variants={sectionVariants}
                transition={{ duration: 0.8, ease: [0.22, 0.61, 0.36, 1] }}
                id="services"
                className="relative z-10 py-32 bg-black/20 backdrop-blur-3xl border-y border-[#2A2F36]"
            >
                <div className="px-6 md:px-12 max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-24">
                    <div className="space-y-8">
                        <h2 className="font-tight text-5xl font-bold leading-tight text-white max-w-md">
                            Transforming <span className="text-[#1A7AFF]">Ideas</span> Into Interfaces.
                        </h2>
                        <p className="text-[#9AA3B2] text-lg leading-relaxed max-w-lg font-light">
                            I specialize in building agentic design systems that empower users and businesses through clarity and precision.
                        </p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                        {PERSON.skills.technical.map((skill, i) => (
                            <div key={i} className="p-8 rounded-[12px] bg-[#0B0F14]/50 border border-[#2A2F36] hover:border-[#1A7AFF]/50 transition-colors group">
                                <div className="w-8 h-8 rounded-[6px] bg-[#1A7AFF]/10 flex items-center justify-center mb-6 group-hover:bg-[#1A7AFF]/20 transition-colors">
                                    <div className="w-1.5 h-1.5 rounded-full bg-[#1A7AFF] shadow-[0_0_8px_#1A7AFF]" />
                                </div>
                                <h3 className="text-white font-bold mb-2">{skill}</h3>
                                <p className="text-xs text-[#7A8AA0] uppercase tracking-widest font-mono">Expertise</p>
                            </div>
                        ))}
                    </div>
                </div>
            </motion.section>

            {/* FOOTER */}
            <footer className="relative z-10 py-32 text-center">
                <motion.div
                    initial="initial"
                    whileInView="whileInView"
                    viewport={sectionVariants.viewport}
                    variants={sectionVariants}
                    transition={{ duration: 0.8, ease: [0.22, 0.61, 0.36, 1] }}
                >
                    <h2 className="font-tight text-5xl md:text-7xl font-bold mb-12">Let’s Build.</h2>
                    <a
                        href={`mailto:${PERSON.contact.email}`}
                        className="text-2xl font-medium text-[#9AA3B2] hover:text-white transition-colors underline decoration-[#1A7AFF] underline-offset-8"
                    >
                        {PERSON.contact.email}
                    </a>

                    <p className="mt-32 text-[#7A8AA0] text-[10px] uppercase tracking-widest leading-loose">
                        © 2026 Manobala MVJ • Crafted with precision and intention.
                    </p>
                </motion.div>
            </footer>
        </main>
    );
}
