"use client";
import { motion } from "framer-motion";
import { useEffect, useState } from "react";
import Image from "next/image";
import { PrimaryButton, SecondaryButton } from "./Buttons";

const useTypingEffect = (text: string, speed: number = 70) => {
    const [displayedText, setDisplayedText] = useState("");

    useEffect(() => {
        let i = 0;
        const interval = setInterval(() => {
            setDisplayedText(text.slice(0, i + 1));
            i++;
            if (i >= text.length) clearInterval(interval);
        }, speed);

        return () => clearInterval(interval);
    }, [text, speed]);

    return displayedText;
};

export default function HeroBlock({ person }: { person: any }) {
    const typingText = useTypingEffect("Crafting Experiences, One Pixel at a Time.");

    return (
        <section className="relative min-h-[90vh] flex flex-col justify-center px-6 md:px-12 pt-20 overflow-hidden">

            <div className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-[1.2fr_0.8fr] gap-12 items-center relative z-10">

                {/* Left Content */}
                <motion.div
                    initial="initial"
                    animate="animate"
                    className="flex flex-col items-start text-left"
                >
                    {/* Status Badge */}
                    <motion.div
                        variants={{
                            initial: { opacity: 0, x: -20 },
                            animate: { opacity: 1, x: 0 }
                        }}
                        transition={{ duration: 0.3, ease: [0.22, 0.61, 0.36, 1] }}
                        className="px-3 py-1 border border-[#2A2F36] rounded-full bg-black/20 backdrop-blur-sm mb-8"
                    >
                        <span className="text-[12px] font-bold uppercase tracking-[0.05em] text-[#7A8AA0]">
                            OPEN FOR PROJECTS
                        </span>
                    </motion.div>

                    {/* Headline with typing animation */}
                    <h1 className="font-tight text-[48px] md:text-[64px] lg:text-[72px] font-bold leading-[1.05] tracking-[-0.01em] text-white max-w-[900px] mb-8 min-h-[150px] md:min-h-[auto]">
                        {typingText}
                        <span className="inline-block w-[3px] h-[0.9em] bg-[#1A7AFF] ml-2 animate-pulse" />
                    </h1>

                    {/* Subtext */}
                    <motion.p
                        variants={{
                            initial: { opacity: 0, x: -20 },
                            animate: { opacity: 1, x: 0 }
                        }}
                        transition={{ duration: 0.3, delay: 0.4, ease: [0.22, 0.61, 0.36, 1] }}
                        className="font-sans text-[18px] text-[#9AA3B2] max-w-[560px] leading-[1.6] mb-12"
                    >
                        {person.summary.split('. ')[0]}. Transforming complex ideas into seamless design intent.
                    </motion.p>

                    {/* Buttons Stack */}
                    <motion.div
                        variants={{
                            initial: { opacity: 0, y: 12 },
                            animate: { opacity: 1, y: 0 }
                        }}
                        transition={{ duration: 0.3, delay: 0.6, ease: [0.22, 0.61, 0.36, 1] }}
                        className="flex flex-col sm:flex-row items-center gap-6"
                    >
                        <PrimaryButton href="#work">View Work</PrimaryButton>
                        <SecondaryButton href="#plans">See Plans</SecondaryButton>
                    </motion.div>
                </motion.div>

                {/* Right Content: Profile Image */}
                <motion.div
                    initial={{ opacity: 0, scale: 0.8, rotate: -5 }}
                    animate={{ opacity: 1, scale: 1, rotate: 0 }}
                    transition={{ duration: 0.8, delay: 0.2, ease: [0.22, 0.61, 0.36, 1] }}
                    className="relative hidden lg:block"
                >
                    <div className="relative w-full aspect-square max-w-[450px] mx-auto overflow-hidden rounded-[32px] border border-[#2A2F36] shadow-2xl shadow-blue-500/10">
                        <Image
                            src="https://i.ibb.co/jPkDRcpd/Whats-App-Image-2025-11-30-at-19-33-18.jpg"
                            alt="Manobala MVJ"
                            fill
                            className="object-cover"
                            unoptimized
                        />
                    </div>

                    {/* Decorative accent */}
                    <div className="absolute -bottom-6 -right-6 w-32 h-32 bg-[#1A7AFF]/10 rounded-full blur-3xl opacity-50" />
                    <div className="absolute -top-6 -left-6 w-32 h-32 bg-purple-500/5 rounded-full blur-3xl opacity-30" />
                </motion.div>

            </div>

        </section>
    );
}
