"use client";
import { motion } from "framer-motion";

export function PrimaryButton({ children, href }: { children: React.ReactNode, href?: string }) {
    return (
        <motion.a
            href={href}
            whileHover={{
                y: -3,
                scale: 1.02,
                boxShadow: "0 10px 30px rgba(37, 117, 252, 0.5), inset 0 0 10px rgba(255, 255, 255, 0.2)"
            }}
            whileTap={{ scale: 0.98 }}
            transition={{ duration: 0.3, ease: [0.22, 0.61, 0.36, 1] }}
            className="relative px-[32px] py-[14px] overflow-hidden rounded-[12px] font-bold text-base inline-flex items-center justify-center cursor-pointer group bg-gradient-to-b from-[#3b82f6] to-[#1d4ed8] border border-white/10 border-t-white/30 text-white shadow-xl"
        >
            <span className="relative z-10 tracking-tight flex items-center gap-2">
                {children}
            </span>
        </motion.a>
    );
}

export function SecondaryButton({ children, href }: { children: React.ReactNode, href?: string }) {
    return (
        <motion.a
            href={href}
            whileHover={{
                y: -3,
                scale: 1.02,
                backgroundColor: "#1f2937",
                boxShadow: "0 10px 30px rgba(0, 0, 0, 0.3)"
            }}
            whileTap={{ scale: 0.98 }}
            transition={{ duration: 0.3, ease: [0.22, 0.61, 0.36, 1] }}
            className="relative px-[32px] py-[14px] overflow-hidden rounded-[12px] font-bold text-base inline-flex items-center justify-center cursor-pointer bg-gradient-to-b from-[#1f2937] to-[#111827] border border-white/5 border-t-white/10 text-white shadow-xl group"
        >
            <span className="relative z-10 tracking-tight transition-colors">
                {children}
            </span>
        </motion.a>
    );
}
