"use client";
import { motion } from "framer-motion";
import Image from "next/image";
import { ArrowUpRight } from "lucide-react";

export default function ProjectCard({ project, index }: { project: any, index: number }) {
    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, ease: [0.22, 0.61, 0.36, 1] }}
            whileHover={{ y: -6, boxShadow: "0 20px 40px rgba(0,0,0,0.4)" }}
            className="group relative h-[480px] rounded-[24px] bg-[#11161C] border border-[#2A2F36] overflow-hidden cursor-pointer"
        >
            <div className="absolute inset-0 z-0 opacity-50 transition-transform duration-700 group-hover:scale-105">
                <Image
                    src={project.image}
                    alt={project.title}
                    fill
                    className="object-cover"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-[#0B0F14] via-[#0B0F14]/40 to-transparent" />
            </div>

            <div className="absolute inset-0 z-10 p-8 flex flex-col justify-end">
                <div className="flex justify-between items-end">
                    <div className="space-y-4">
                        <span className="px-3 py-1 rounded-[6px] bg-[#1A7AFF]/10 border border-[#1A7AFF]/20 text-[#1A7AFF] text-[10px] uppercase font-bold tracking-widest">
                            {project.role.split(' · ')[0]}
                        </span>
                        <h3 className="font-tight text-3xl md:text-4xl font-bold text-white group-hover:text-[#1A7AFF] transition-colors">
                            {project.title}
                        </h3>
                    </div>
                    <div className="w-12 h-12 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white backdrop-blur-md group-hover:bg-[#1A7AFF] group-hover:border-[#1A7AFF] transition-all duration-300">
                        <ArrowUpRight className="w-5 h-5 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                    </div>
                </div>
            </div>
        </motion.div>
    );
}
